@Component({
  selector: 'app-data-table',
  standalone: true,
  imports: [NgFor],
  template: `
    <table>
      <tr *ngFor="let row of rows()" (click)="rowSelected.emit(row)">
        <td>{{ row.label }}</td>
        <td><ng-content select="[actions]"></ng-content></td>
      </tr>
    </table>
  `,
})
export class DataTableComponent<T extends { label: string }> {
  rows = input.required<T[]>();
  rowSelected = output<T>();
}

